// ===== Appellations: an encyclopedia entry for every appellation =====
// Lists come from the Vitis Mundi atlas (assets/js/appellations/<cc>.js, generated by tools/build_appellations.py).
// Full entries, researched from the official specifications, live in assets/js/appellations/full/<cc>/<region>.js
// as APXF["<atlas id>"] = {...}. An appellation without a full entry shows its atlas summary until one is written.
var APX = {}, APXF = {};
const APP_FLAGS = { fr: "France", it: "Italy", es: "Spain", pt: "Portugal", us: "United States" };
const APP_LEVELS = { fr: "AOC/AOP", it: "DOCG and DOC", es: "DOCa, DO and Vino de Pago", pt: "DOC", us: "AVA" };
const appLoads = {}, appDone = {};
function appLoad(src) {
  return appLoads[src] || (appLoads[src] = new Promise(ok => {
    const fin = () => { appDone[src] = true; ok(); };
    const s = document.createElement("script"); s.src = src; s.onload = fin; s.onerror = fin; document.head.appendChild(s);
  }));
}
function appNeed(cc, rslugs) {
  const ps = [], need = src => { if (!appDone[src]) ps.push(appLoad(src)); };
  if (!APX[cc]) need(`assets/js/appellations/${cc}.js`);
  (rslugs || []).forEach(r => { const row = APPS[cc].regions.find(x => x[0] === r); if (row && row[3]) need(`assets/js/appellations/full/${cc}/${r}.js`); });
  return ps.length ? Promise.all(ps) : null;
}
function appWait(p) { if (p) postHooks.push(() => p.then(() => { if ((location.hash || "").startsWith("#apps")) route(); })); return `<div class="wrap"><p class="muted">Loading the appellations…</p></div>`; }
const appHref = (...p) => "#apps/" + p.map(encodeURIComponent).join("/");
const appBadge = (cc, id) => APXF[id] ? `<span class="pill good">full entry</span>` : "";

function viewApps() {
  const parts = decodeURIComponent((location.hash || "").slice(1)).split("/").slice(1);
  const [cc, a, b] = parts;
  if (!cc || !APPS[cc]) return appsHome();
  if (a === "r") { const p = appNeed(cc, [b]); return p ? appWait(p) : appsRegion(cc, b); }
  if (a) {
    let p = appNeed(cc); if (p) return appWait(p);
    const it = APX[cc].items[a]; if (!it) return `<div class="wrap"><h1>Not found</h1><a class="btn" href="${appHref(cc)}">Back</a></div>`;
    p = appNeed(cc, [it.rslug]); return p ? appWait(p) : appsEntry(cc, a);
  }
  const p = appNeed(cc); return p ? appWait(p) : appsCountry(cc);
}

function appsHome() {
  const tot = Object.values(APPS).reduce((s, c) => s + c.n, 0), full = Object.values(APPS).reduce((s, c) => s + c.full, 0);
  return `<div class="wrap"><div class="eyebrow">Appellations</div><h1>Every <em>appellation.</em></h1>
  <p class="lede">An entry for each of ${tot.toLocaleString()} appellations in France, Italy, Spain, Portugal and the United States: where it is, what the rules allow, why the wine tastes as it does, and who makes it. ${full ? `${full} have full entries so far; the rest show the atlas summary until theirs is written.` : "Full entries are being written country by country; until then each shows its atlas summary."}</p>
  <div class="grid g3">${Object.entries(APPS).map(([cc, c]) => `<a class="card" href="${appHref(cc)}" style="text-decoration:none"><b>${esc(c.name)}</b><div class="small muted">${c.n} ${APP_LEVELS[cc]} · ${c.regions.length} regions</div><div class="small" style="margin-top:6px">${c.full ? `${c.full} full entries` : "Atlas summaries"}</div></a>`).join("")}</div></div>`;
}

function appsCountry(cc) {
  const C = APX[cc], I = APPS[cc];
  return `<div class="wrap"><div class="eyebrow"><a href="#apps">Appellations</a> · ${esc(I.name)}</div><h1>${esc(I.name)}</h1>
  ${C.country.tagline ? `<p class="lede">${esc(C.country.tagline)}</p>` : ""}
  <input type="text" data-appq="${cc}" placeholder="Search ${I.n} ${APP_LEVELS[cc]}" style="max-width:380px"><div id="appq"></div>
  <h2>Regions</h2><div class="grid g3">${C.regions.map((r, i) => { const row = I.regions[i]; return `<a class="card" href="${appHref(cc, "r", r.slug)}" style="text-decoration:none"><b>${esc(r.name)}</b><div class="small muted">${r.ids.length} appellation${r.ids.length === 1 ? "" : "s"}${row && row[3] ? ` · ${row[3]} full` : ""}</div>${r.tagline ? `<p class="small" style="margin:6px 0 0;color:var(--ink2)">${esc(r.tagline)}</p>` : ""}</a>`; }).join("")}</div></div>`;
}
function appSearch(cc, q) {
  const C = APX[cc]; if (!C) return ""; q = q.trim().toLowerCase(); if (q.length < 2) return "";
  const hits = Object.entries(C.items).filter(([, it]) => it.name.toLowerCase().includes(q) || (it.grapes || "").toLowerCase().includes(q)).slice(0, 40);
  return hits.length ? `<table class="t">${hits.map(([id, it]) => `<tr><td><a href="${appHref(cc, id)}"><b>${esc(it.name)}</b></a> ${appBadge(cc, id)}</td><td class="small muted">${esc(it.region)}${it.subregion ? " · " + esc(it.subregion) : ""}</td></tr>`).join("")}</table>` : `<p class="small muted">No match.</p>`;
}

function appsRegion(cc, rs) {
  const C = APX[cc], r = C.regions.find(x => x.slug === rs); if (!r) return `<div class="wrap"><h1>Region not found</h1><a class="btn" href="${appHref(cc)}">Back</a></div>`;
  const groups = {}; r.ids.forEach(id => { const s = C.items[id].subregion || ""; (groups[s] = groups[s] || []).push(id); });
  return `<div class="wrap"><div class="eyebrow"><a href="#apps">Appellations</a> · <a href="${appHref(cc)}">${esc(APPS[cc].name)}</a></div><h1>${esc(r.name)}</h1>${r.tagline ? `<p class="lede">${esc(r.tagline)}</p>` : ""}
  ${Object.entries(groups).sort((a, b) => a[0].localeCompare(b[0])).map(([s, ids]) => `${s ? `<h2>${esc(s)}</h2>` : ""}<div class="tw"><table class="t">${ids.map(id => { const it = C.items[id]; return `<tr><td style="width:34%"><a href="${appHref(cc, id)}"><b>${esc(it.name)}</b></a> ${appBadge(cc, id)}<div class="small muted">${esc([it.cat, it.subcat].filter(Boolean).join(" · "))}</div></td><td class="small">${esc((it.styles || []).join(", "))}<div class="muted">${esc(it.grapes || "")}</div></td></tr>`; }).join("")}</table></div>`).join("")}</div>`;
}

function appsEntry(cc, id) {
  const it = APX[cc].items[id], F = APXF[id], reg = APX[cc].regions.find(x => x.slug === it.rslug);
  const ids = reg ? reg.ids : [], i = ids.indexOf(id), prev = ids[i - 1], next = ids[i + 1];
  const facts = F ? F.facts : [["Category", [it.cat, it.subcat].filter(Boolean).join(" · ")], ["Recognized", it.created], ["Area", it.area_ha ? `${Number(it.area_ha).toLocaleString()} ha` : ""], ["Styles", (it.styles || []).join(", ")], ["Grapes", it.grapes]];
  const body = F ? F.sections.map(([h, html]) => `<h2>${esc(h)}</h2>${html}`).join("")
    : `<p>${esc(it.summary || "")}</p>${it.terroir ? `<h2>The place</h2><p>${esc(it.terroir)}</p>` : ""}${it.nerd_note ? `<h2>Worth knowing</h2><p>${esc(it.nerd_note)}</p>` : ""}${(it.producers || []).length ? `<h2>Producers</h2><p>${it.producers.map(esc).join(", ")}</p>` : ""}
      <div class="card" style="margin-top:24px"><p class="small muted" style="margin:0">This appellation's full entry, with its rules from the official specification, is still being written. The text above is the Vitis Mundi atlas summary.</p></div>`;
  return `<div class="wrap read"><div class="eyebrow"><a href="#apps">Appellations</a> · <a href="${appHref(cc)}">${esc(APPS[cc].name)}</a> · <a href="${appHref(cc, "r", it.rslug)}">${esc(it.region)}</a>${it.subregion ? " · " + esc(it.subregion) : ""}</div>
  <h1>${esc(it.name)}</h1>${F && F.lede ? `<p class="lede">${esc(F.lede)}</p>` : ""}
  <div class="tw"><table class="t">${facts.filter(f => f[1]).map(([k, v]) => `<tr><td style="width:30%" class="small muted">${esc(k)}</td><td class="small">${esc(String(v))}</td></tr>`).join("")}</table></div>
  <div class="prose">${body}</div>
  ${F && F.producers && F.producers.length ? `<h2>Producers to know</h2><ul>${F.producers.map(p => `<li>${p}</li>`).join("")}</ul>` : ""}
  <p class="small"><a href="https://vitismundi.app/#${encodeURIComponent(id)}" target="_blank" rel="noopener">Open ${esc(it.name)} on the Vitis Mundi atlas &#8599;</a></p>
  ${F && F.sources ? `<p class="small muted">Sources: ${F.sources.map(([t, u]) => `<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`).join(" · ")}. Checked ${esc(F.checked || "")}.</p>` : ""}
  <div class="row" style="justify-content:space-between;margin-top:24px">${prev ? `<a class="btn sm" href="${appHref(cc, prev)}">&larr; ${esc(APX[cc].items[prev].name)}</a>` : "<span></span>"}${next ? `<a class="btn sm" href="${appHref(cc, next)}">${esc(APX[cc].items[next].name)} &rarr;</a>` : ""}</div></div>`;
}
